-- ----- source: ../src/database/migrations/098_update_grn_number_generator.sql -----
-- Update GRN number generator to format: GRN/VRP/{CIRCLE_CODE}-{CLUSTER_CODE}/{YY-YY}/{NNN}
-- Example: GRN/VRP/RJ-UDP/25-26/001

BEGIN;

CREATE OR REPLACE FUNCTION generate_grn_number(p_circle_id INTEGER, p_cluster_id INTEGER)
RETURNS VARCHAR(50) AS $$
DECLARE
  v_circle_code TEXT;
  v_cluster_code TEXT;
  v_fy_start INT;
  v_fy_end INT;
  v_fy TEXT;
  v_prefix TEXT;
  v_next INT;
  v_num VARCHAR(50);
BEGIN
  SELECT COALESCE(tc.code, 'NA') INTO v_circle_code FROM telecom_circles tc WHERE tc.id = p_circle_id;
  IF v_circle_code IS NULL THEN v_circle_code := 'NA'; END IF;

  SELECT COALESCE(c.code, 'NA') INTO v_cluster_code FROM clusters c WHERE c.id = p_cluster_id;
  IF v_cluster_code IS NULL THEN v_cluster_code := 'NA'; END IF;

  IF EXTRACT(MONTH FROM CURRENT_DATE) >= 4 THEN
    v_fy_start := EXTRACT(YEAR FROM CURRENT_DATE);
  ELSE
    v_fy_start := EXTRACT(YEAR FROM CURRENT_DATE) - 1;
  END IF;
  v_fy_end := v_fy_start + 1;
  v_fy := LPAD((v_fy_start % 100)::TEXT, 2, '0') || '-' || LPAD((v_fy_end % 100)::TEXT, 2, '0');

  v_prefix := 'GRN/VRP/' || v_circle_code || '-' || v_cluster_code || '/' || v_fy || '/';

  SELECT COALESCE(MAX(NULLIF(split_part(grn_number, '/', 5), '')::INT), 0) + 1
  INTO v_next
  FROM goods_receipts
  WHERE grn_number LIKE v_prefix || '%';

  v_num := v_prefix || LPAD(v_next::TEXT, 3, '0');
  RETURN v_num;
END;
$$ LANGUAGE plpgsql;

COMMIT;




-- ----- source: ../src/database/migrations/099_add_grn_workflow_and_permissions.sql -----
-- Add GRN workflow statuses/columns and permissions
BEGIN;

-- 1) Extend grn_status enum with approval states
DO $$
BEGIN
  -- Add values if not present
  IF NOT EXISTS (
    SELECT 1 FROM pg_enum e
    JOIN pg_type t ON t.oid = e.enumtypid
    WHERE t.typname = 'grn_status' AND e.enumlabel = 'pending_approval'
  ) THEN
    ALTER TYPE grn_status ADD VALUE IF NOT EXISTS 'pending_approval';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_enum e
    JOIN pg_type t ON t.oid = e.enumtypid
    WHERE t.typname = 'grn_status' AND e.enumlabel = 'approved'
  ) THEN
    ALTER TYPE grn_status ADD VALUE IF NOT EXISTS 'approved';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_enum e
    JOIN pg_type t ON t.oid = e.enumtypid
    WHERE t.typname = 'grn_status' AND e.enumlabel = 'rejected'
  ) THEN
    ALTER TYPE grn_status ADD VALUE IF NOT EXISTS 'rejected';
  END IF;
END$$;

-- 2) Add workflow columns to goods_receipts
ALTER TABLE goods_receipts
  ADD COLUMN IF NOT EXISTS workflow_instance_id INTEGER,
  ADD COLUMN IF NOT EXISTS submitted_at TIMESTAMP,
  ADD COLUMN IF NOT EXISTS submitted_by INTEGER REFERENCES users(id),
  ADD COLUMN IF NOT EXISTS approved_at TIMESTAMP,
  ADD COLUMN IF NOT EXISTS approved_by INTEGER REFERENCES users(id),
  ADD COLUMN IF NOT EXISTS rejected_at TIMESTAMP,
  ADD COLUMN IF NOT EXISTS rejected_by INTEGER REFERENCES users(id),
  ADD COLUMN IF NOT EXISTS rejection_reason TEXT;

-- 3) Ensure goods_receipt feature has submit and approve permissions
UPDATE features f
SET available_permissions = (
  CASE
    WHEN f.available_permissions IS NULL THEN '[]'::jsonb
    ELSE f.available_permissions
  END
  || (CASE WHEN NOT (f.available_permissions ? 'submit') THEN '"submit"'::jsonb ELSE '[]'::jsonb END)
  || (CASE WHEN NOT (f.available_permissions ? 'approve') THEN '"approve"'::jsonb ELSE '[]'::jsonb END)
)
WHERE f.name = 'goods_receipt' AND f.module_id = (SELECT id FROM modules WHERE name = 'procurement');

COMMIT;




